import plistlib, subprocess, sys, pathlib

def signer(path):
    out = subprocess.run(["codesign", "-dvv", path], capture_output=True, text=True).stderr
    if "Signature=adhoc" in out:
        return "adhoc"
    for line in out.splitlines():
        if line.startswith("Authority="):
            return line.split("=", 1)[1]          # first Authority = leaf cert
    return "unsigned"

for plist in sorted(pathlib.Path(sys.argv[1]).glob("*.plist")):
    job = plistlib.loads(plist.read_bytes())
    prog = job.get("Program") or job.get("ProgramArguments", [""])[0]
    who = signer(prog)
    flags = []
    if job["Label"].startswith("com.apple.") and who not in ("Software Signing", "macOS Software Signing"):
        flags.append("apple-label-not-apple-signed")
    if "/." in prog or prog.startswith(("/tmp/", "/private/tmp/", "/Users/Shared/")):
        flags.append("odd-location")
    if who in ("adhoc", "unsigned"):
        flags.append(who)
    if pathlib.Path(prog).name in ("sh", "bash", "zsh", "osascript", "python3"):
        flags.append("interpreter")               # payload is in the arguments
    if job.get("RunAtLoad") and job.get("KeepAlive"):
        flags.append("always-on")
    print(f"{plist.name}: signer={who!r} flags={flags or 'none'}")

# $ python3 hunt_agents.py fixtures/LaunchAgents
# com.apple.updater.plist: signer='adhoc' flags=['apple-label-not-apple-signed', 'odd-location', 'adhoc', 'always-on']
# com.example.backup.plist: signer='Developer ID Application: Google LLC (EQHXZ8M8AV)' flags=none

#include <os/log.h>
int main(int argc, char **argv) {
    os_log_t log = os_log_create("dev.example.lab", "auth");
    const char *user = argc > 1 ? argv[1] : "nobody";   /* built at run time */
    os_log(log, "login ok for %{public}s", user);
    os_log(log, "login ok for %s", user);           /* no modifier */
    os_log_error(log, "3 failed attempts for %{public}s", user);
    return 0;
}
